<script lang="ts">import {page} from '$app/state';import {goto} from '$app/navigation';import {adopt} from '$lib/session.svelte';import {callback} from '$lib/oidc';let error=$state('');$effect(()=>{void finish()});async function finish(){try{const result=await callback(page.url.searchParams.get('code')||'',page.url.searchParams.get('state')||'');adopt(result.tokens);await goto(result.returnTo||'/')}catch(e){error=e instanceof Error?e.message:String(e)}}</script><main class="shell"><div class="card"><h1>Signing you in…</h1>{#if error}<p class="error">{error}</p><a class="button" href="/">Try again</a>{/if}</div></main>
